require_once __DIR__.'/../includes/auth.php';requireLogin();if(!canManageNews()){http_response_code(403);exit('غير مصرح.');}$errors=[];
if(isPost()){verifyCsrf();$title=trim($_POST['title']??'');$summary=trim($_POST['summary']??'');$details=sanitizeHtml($_POST['details']??'');$cat=(int)($_POST['category_id']??0);$seoTitle=trim($_POST['seo_title']??'');$seoDescription=trim($_POST['seo_description']??'');$status=(string)($_POST['status']??'draft');$role=currentUser()['role'];$allowedStatuses=$role==='author'?['draft','pending']:['draft','pending','published','archived'];if(!in_array($status,$allowedStatuses,true))$status='draft';$errors=array_merge($errors,articleValidationErrors($title,$summary,$details,$cat,$seoTitle,$seoDescription));try{$image=uploadImage('image');}catch(RuntimeException $x){$errors[]=$x->getMessage();}$featured=$role==='author'?0:(!empty($_POST['is_featured'])?1:0);$breaking=$role==='author'?0:(!empty($_POST['is_breaking'])?1:0);$published=$status==='published'?date('Y-m-d H:i:s'):null;if(!$errors){$s=db()->prepare('INSERT INTO news(title,slug,summary,details,image,category_id,user_id,status,is_featured,is_breaking,views_count,seo_title,seo_description,published_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,0,?,?,?,NOW(),NOW())');$s->execute([$title,uniqueSlug('news',$title),$summary,$details,$image,$cat,currentUser()['id'],$status,$featured,$breaking,$seoTitle,$seoDescription,$published]);flash('success','تم إنشاء الخبر بنجاح.');redirect(url('admin/news.php'));}}
